import React, { useContext,useState } from "react";
import ProductContext from "./store2/product-context";

import "./AddProduct.css";
import CartContext from "../store/cart-context";
const AddProduct = () => {
  const { openProduct, selectedItem } = useContext(ProductContext);
  const { addItems } = useContext(CartContext);

  const [itemQuantities, setItemQuantities] = useState({});

  const updateQuantity = (itemId, size) => {
    if (itemQuantities[itemId] && itemQuantities[itemId][size] > 0) {
      const updatedQuantities = { ...itemQuantities };
      updatedQuantities[itemId] = { ...updatedQuantities[itemId] };
      updatedQuantities[itemId][size] = updatedQuantities[itemId][size] - 1;
      setItemQuantities(updatedQuantities);
    }
  };
  

  //console.log("from addProduct" ,selectedItem);
  // this logic ::not adding different item  it was adding same item only
  // const addToCart = (size, name, price) => {
  //   if (selectedItem) {
  //     console.log("Selected item:", selectedItem);
  //     const item = {
  //       id: selectedItem.id,
  //       name: name,
  //       price: price,
  //       size: size,
  //       amount: 1, // Set amount to 1
  //     };
  //     addItems(item); // Call addItems function from CartContext
  //   }
  // };
  //
  // second logic   ::   caused all same button triggred
  // const addToCart = (size) => {
  //   if (selectedItem && selectedItem.length > 0) {
  //     selectedItem.forEach((selectedItem) => {
  //       const item = {
  //         id: selectedItem.id,
  //         name: selectedItem.name,
  //         price: selectedItem.price,
  //         size: size,
  //         amount: 1, // Set amount to 1
  //       };
  //       addItems(item); // Call addItems function from CartContext
  //     });
  //   }
  // };
  // fourth logic   worked perfecctly
  const addToCart = (size, selectedItem) => {
    if (selectedItem) {
      const item = {
        id: selectedItem.id,
        name: selectedItem.name,
        price: selectedItem.price,
        size: size,
        amount: 1,
      };
      addItems(item);
     
    }
    
  };

 

  return (
    <div>
      {openProduct && selectedItem && (
        <div className="addProduct">
          {selectedItem.map((item) => (
            <div key={item.id}>
              <h2>{item.name}</h2>
              <p>Description: {item.description}</p>
              <p>Price: Rs {item.price}</p>
              <button onClick={() => addToCart("Large", item)}>
              Buy Large {itemQuantities[item.id]?.large ?? item.large}
              </button>
              <button onClick={() => addToCart("Medium", item)}>
              Buy Medium {itemQuantities[item.id]?.medium ?? item.medium}
              </button>
              <button onClick={() => addToCart("Small", item)}>
              Buy Small {itemQuantities[item.id]?.small ?? item.small}
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default AddProduct;
